<script lang="ts">
  import { fetiche } from '../stores/fetiche.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import type { FeticheBerryFeedSnapshot, FeticheStatBlock } from '../lib/feticheSnapshot.ts';
  import { formatNumber, formatNumberHeader } from '../../formatters.js';
  import { getBerryTreeRecipe } from '../../constants/balance/berryTree.ts';
  import { miltankFarmTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { buildFeticheBerryTooltipContent } from '../lib/feticheBerryTooltip.ts';

  type StatKey = keyof FeticheStatBlock;

  const STAT_KEYS: StatKey[] = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'];

  const STAT_I18N_KEYS: Record<StatKey, string> = {
    hp: 'header.statHp',
    attack: 'header.statAtk',
    spattack: 'header.statSpAtk',
    defense: 'header.statDef',
    spdefense: 'header.statSpDef',
    speed: 'header.statSpd',
  };

  const STAT_LABEL_FALLBACKS: Record<StatKey, string> = {
    hp: 'HP',
    attack: 'ATK',
    spattack: 'SP.A',
    defense: 'DEF',
    spdefense: 'SP.D',
    speed: 'SPD',
  };

  let snap = $derived(fetiche.snapshot);
  let ui = $derived(snap.ui);
  let mood = $derived(snap.mood);
  let pendingSpeciesKey = $state<string | null>(null);

  let pendingSpeciesName = $derived.by((): string => {
    if (!pendingSpeciesKey) return '';
    return snap.speciesChoices.find((s) => s.speciesKey === pendingSpeciesKey)?.name ?? pendingSpeciesKey;
  });

  let chooseConfirmLabel = $derived.by((): string => {
    if (!pendingSpeciesKey) return ui.chooseConfirm;
    return ui.chooseConfirmPrompt.replace('{name}', pendingSpeciesName);
  });

  let statLabels = $derived.by((): Record<StatKey, string> => {
    const gm = game as GameRuntime | null;
    if (!gm) return { ...STAT_LABEL_FALLBACKS };
    void gm.language;
    const labels = { ...STAT_LABEL_FALLBACKS };
    for (const key of STAT_KEYS) {
      const raw = gm.t?.(STAT_I18N_KEYS[key]) ?? STAT_LABEL_FALLBACKS[key];
      labels[key] = raw.replace(/\s*:\s*$/, '').trim();
    }
    return labels;
  });

  let xpProgressText = $derived.by((): string => {
    if (snap.isMaxLevel) return ui.maxLevelLabel;
    return ui.xpProgress
      .replace('{current}', formatNumber(snap.xp))
      .replace('{next}', formatNumber(snap.xpToNext));
  });

  let gainsTotalText = $derived.by((): string => {
    return ui.gainsTotalLabel.replace('{value}', formatNumberHeader(snap.gainsTotalPerSec));
  });

  let bestBerry = $derived(snap.feedBerries.find((berry) => berry.canFeed) ?? null);

  let feedBlocked = $derived(snap.hasStomachCramp || !snap.isHungry || snap.feedBerries.length === 0);

  let canFillBest = $derived(
    !!bestBerry
    && bestBerry.canFeed
    && bestBerry.taste !== 'hated'
    && bestBerry.qty > 0,
  );

  let feedBestLabel = $derived.by((): string => {
    if (!bestBerry) return ui.feedTitle;
    const base = (ui.feedBest || 'Nourrir · {name} {mark}')
      .replace('{name}', bestBerry.name)
      .replace('{mark}', bestBerry.tasteIcon);
    return `${base} (×${formatNumber(bestBerry.qty)})`;
  });

  let cravingKeys = $derived(new Set(mood?.cravingBerryKeys ?? []));

  function byStockFirst(berries: FeticheBerryFeedSnapshot[]): FeticheBerryFeedSnapshot[] {
    return berries.slice().sort((a, b) => Number(b.qty > 0) - Number(a.qty > 0) || a.name.localeCompare(b.name));
  }

  let cravingChips = $derived(byStockFirst(mood?.cravings ?? []));
  let lovedChips = $derived(byStockFirst((mood?.lovedNow ?? []).filter((berry) => !cravingKeys.has(berry.berryKey))));
  let hatedChips = $derived(byStockFirst(mood?.hatedNow ?? []));

  let transmissionText = $derived.by((): string => {
    return ui.transmissionLabel.replace(/\{sec\}/g, formatNumber(snap.transmissionSec));
  });

  function tasteClass(taste: string): string {
    return `fetiche-taste-${taste}`;
  }

  function hasRecipe(berryKey: string): boolean {
    return getBerryTreeRecipe(berryKey) != null;
  }

  function fmtContrib(value: number): string {
    return ui.gainsNowLabel.replace('{value}', formatNumberHeader(value));
  }

  function fmtNextLevel(key: StatKey): string | null {
    const next = snap.gainsAtNextLevel?.[key];
    if (next == null || next <= snap.gainsPerSec[key]) return null;
    return ui.gainsNextLevelHint.replace('{value}', `${formatNumberHeader(next)}/s`);
  }

  function statChipTitle(key: StatKey): string | undefined {
    const nextHint = fmtNextLevel(key);
    if (!nextHint) return undefined;
    return `${ui.levelLabel} ${snap.level + 1}: ${nextHint}`;
  }

  function berryHandlers(berry: FeticheBerryFeedSnapshot, showQty = false) {
    return miltankFarmTooltipHandlers(() =>
      buildFeticheBerryTooltipContent(berry, ui, { showQty }),
    );
  }

  function moodInfoHandlers() {
    return miltankFarmTooltipHandlers(() => ({
      title: mood?.moodLabel ?? ui.moodTitle,
      body: ui.moodRulesLine,
    }));
  }
</script>

<div class="fetiche-modal-content">
  {#snippet berryChip(berry: FeticheBerryFeedSnapshot)}
    {@const recipe = hasRecipe(berry.berryKey)}
    {@const tip = berryHandlers(berry)}
    <button
      type="button"
      class={['fetiche-berry-chip miltank-farm-tooltip-host', { 'is-empty': berry.qty <= 0, 'has-stock': berry.qty > 0 }]}
      data-tooltip-variant="miltank-farm"
      aria-label={recipe ? `${berry.name} — ${ui.recipeLink}` : berry.name}
      data-action={recipe ? 'openBerryTreeModal' : undefined}
      onmouseenter={tip.onmouseenter}
      onmouseleave={tip.onmouseleave}
      onfocus={tip.onfocus}
      onblur={tip.onblur}
      onclick={recipe ? undefined : tip.onclick}
      onkeydown={recipe ? undefined : tip.onkeydown}
    >
      {#if berry.iconUrl}
        <img src={berry.iconUrl} alt="" width="22" height="22" />
      {/if}
      <span class="fetiche-berry-chip-qty">×{formatNumber(berry.qty)}</span>
    </button>
  {/snippet}
  {#if snap.showOnboarding}
    <div class="fetiche-onboarding-banner mastery-panel fetiche-lcd-screen" role="note">
      <p class="fetiche-onboarding-text">{ui.gainsHint}</p>
      {#if snap.hasChosen}
        <p class="fetiche-onboarding-text fetiche-onboarding-transmission">{transmissionText}</p>
      {/if}
      <button type="button" class="fetiche-onboarding-dismiss" data-action="dismissFeticheOnboarding">
        OK
      </button>
    </div>
  {/if}
  {#if !snap.hasChosen}
    <section class="fetiche-panel mastery-panel fetiche-lcd-screen" aria-label={ui.chooseTitle}>
      <h3 class="fetiche-section-title mastery-frame-title">{ui.chooseTitle}</h3>
      <p class="fetiche-hint">{ui.chooseHint}</p>
      {#if snap.speciesChoices.length === 0}
        <p class="fetiche-empty">{ui.chooseEmpty}</p>
      {:else}
        <div class="fetiche-species-grid">
          {#each snap.speciesChoices as species (species.speciesKey)}
            <button
              type="button"
              class={['fetiche-species-card', { selected: pendingSpeciesKey === species.speciesKey }]}
              onclick={() => { pendingSpeciesKey = species.speciesKey; }}
            >
              <img src={species.spriteUrl} alt="" width="88" height="88" class="fetiche-species-sprite" />
              <span class="fetiche-species-name">{species.name}</span>
            </button>
          {/each}
        </div>
        {#if pendingSpeciesKey}
          <button
            type="button"
            class="fetiche-choose-confirm-btn"
            data-action="chooseFeticheSpecies"
            data-arg={pendingSpeciesKey}
          >
            {chooseConfirmLabel}
          </button>
        {/if}
      {/if}
    </section>
  {:else}
    <section
      class={['fetiche-pet-stage mastery-panel fetiche-lcd-screen', { 'is-hungry': snap.isHungry, 'has-cramp': snap.hasStomachCramp }]}
      aria-label={snap.displaySpeciesName || snap.speciesName}
    >
      <div class="fetiche-pet-layout">
        <div class="fetiche-pet-side">
          <div class="fetiche-sprite-anchor">
            <div class="sprite-platform" aria-hidden="true"></div>
            <img src={snap.spriteUrl} alt="" class="fetiche-pet-sprite" />
          </div>
          <div class="fetiche-pet-header">
            <span class="fetiche-level-badge fetiche-mastery-badge">{snap.level}</span>
            <span class="fetiche-pet-name">{snap.displaySpeciesName || snap.speciesName}</span>
            {#if snap.isHungry || snap.hasStomachCramp}
              <div class="fetiche-pet-badges">
                {#if snap.isHungry}
                  <span class="fetiche-status-badge fetiche-badge-hungry">{ui.hungryLabel}</span>
                {/if}
                {#if snap.hasStomachCramp}
                  <span class="fetiche-status-badge fetiche-badge-cramp">
                    {ui.crampLabel}
                    {#if snap.crampCountdownLabel}
                      <span class="fetiche-cramp-countdown">{snap.crampCountdownLabel}</span>
                    {/if}
                  </span>
                {/if}
              </div>
            {/if}
          </div>
          <p class="fetiche-gains-total fetiche-gains-total-hero">{gainsTotalText}</p>
        </div>

        <div class="fetiche-pet-meters">
        <div class="fetiche-satiety-row">
        <div class="fetiche-xp-block fetiche-satiety-meter">
          <div class="fetiche-xp-header">
            <span class="fetiche-satiety-label">{ui.satietyLabel}</span>
            <span class="fetiche-satiety-value">{snap.satiety}/{snap.satietyMax}</span>
          </div>
          <div class={['fetiche-bar-wrap fetiche-bar-wrap--lg fetiche-bar-wrap--satiety', { 'is-low': snap.satietyPct < 25 }]} title={ui.satietyLabel}>
            <div class="fetiche-bar fetiche-bar-satiety" style="width: {snap.satietyPct}%"></div>
          </div>
        </div>

        <div class="fetiche-feed-inline" aria-label={ui.feedTitle}>
          {#if feedBlocked}
            <button type="button" class="fetiche-feed-best" disabled>{ui.feedTitle}</button>
          {:else if bestBerry}
            {@const feedTip = berryHandlers(bestBerry, true)}
            <div class="fetiche-feed-actions">
              <button
                type="button"
                class={['fetiche-feed-best miltank-farm-tooltip-host', tasteClass(bestBerry.taste)]}
                data-action="feedFeticheBerry"
                data-arg={bestBerry.berryKey}
                data-tooltip-variant="miltank-farm"
                disabled={!bestBerry.canFeed}
                onmouseenter={feedTip.onmouseenter}
                onmouseleave={feedTip.onmouseleave}
                onfocus={feedTip.onfocus}
                onblur={feedTip.onblur}
              >
                {#if bestBerry.iconUrl}
                  <img src={bestBerry.iconUrl} alt="" width="22" height="22" />
                {/if}
                <span class="fetiche-feed-best-label">{feedBestLabel}</span>
              </button>
              {#if canFillBest}
                <button type="button" class="btn-2 fetiche-fill-btn" data-action="fillFetiche" data-arg={bestBerry.berryKey}>{ui.fillBtn}</button>
              {/if}
            </div>
          {/if}
        </div>
        </div>
        {#if feedBlocked}
          <p class="fetiche-hint">
            {#if snap.hasStomachCramp}
              {ui.crampLabel}
              {#if snap.crampCountdownLabel}
                <span class="fetiche-cramp-countdown"> ({snap.crampCountdownLabel})</span>
              {/if}
            {:else if snap.feedBerries.length === 0}
              {ui.noBerries}
            {:else}
              {ui.satietyFull}
            {/if}
          </p>
          {#if snap.nextMealLabel}
            <p class="fetiche-hint">{snap.nextMealLabel}</p>
          {/if}
        {/if}

        <div class="fetiche-xp-block">
          <div class="fetiche-xp-header">
            <span class="fetiche-xp-label">{ui.xpLabel}</span>
            <span class="fetiche-xp-progress">{xpProgressText}</span>
          </div>
          <div
            class={['fetiche-bar-wrap fetiche-bar-wrap--lg fetiche-bar-wrap--xp', { 'is-max': snap.isMaxLevel }]}
            role="progressbar"
            aria-valuenow={snap.isMaxLevel ? 100 : snap.xpPct}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label={ui.xpLabel}
          >
            <div class="fetiche-bar fetiche-bar-xp" style="width: {snap.isMaxLevel ? 100 : snap.xpPct}%"></div>
          </div>
        </div>
        </div>
      </div>
      {#if mood}
        <div class="fetiche-mood-banner" aria-label={ui.moodTitle}>
          <div class="fetiche-mood-head">
            <span class="fetiche-mood-title">{mood.moodLabel}</span>
            <button
              type="button"
              class="fetiche-mood-info miltank-farm-tooltip-host"
              data-tooltip-variant="miltank-farm"
              aria-label={ui.moodInfoLabel}
              {...moodInfoHandlers()}
            >ⓘ</button>
            <span class="fetiche-mood-countdown">
              <svg class="fetiche-mood-clock" viewBox="0 0 16 16" width="14" height="14" aria-hidden="true">
                <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" stroke-width="1.5"></circle>
                <path d="M8 4.5V8l2.5 1.5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"></path>
              </svg>
              {mood.countdownLabel}
            </span>
          </div>
          <div class="fetiche-mood-columns">
            <div class="fetiche-mood-col">
              <div class="fetiche-mood-line">
                <span class="fetiche-mood-list-label">{ui.cravingsTitle}</span>
                <span class="fetiche-craving-tag">{ui.cravingsBonusTag}</span>
              </div>
              {#if cravingChips.length > 0}
                <div class="fetiche-berry-chips">
                  {#each cravingChips as berry (berry.berryKey)}
                    {@render berryChip(berry)}
                  {/each}
                </div>
              {/if}
            </div>
            <div class="fetiche-mood-col fetiche-mood-list-loved">
              <div class="fetiche-mood-line">
                <span class="fetiche-mood-list-label">{ui.lovesLabel}</span>
              </div>
              {#if lovedChips.length > 0}
                <div class="fetiche-berry-chips">
                  {#each lovedChips as berry (berry.berryKey)}
                    {@render berryChip(berry)}
                  {/each}
                </div>
              {/if}
            </div>
            <div class="fetiche-mood-col fetiche-mood-list-hated">
              <div class="fetiche-mood-line">
                <span class="fetiche-mood-list-label">{ui.hatesLabel}</span>
              </div>
              {#if hatedChips.length > 0}
                <div class="fetiche-berry-chips">
                  {#each hatedChips as berry (berry.berryKey)}
                    {@render berryChip(berry)}
                  {/each}
                </div>
              {/if}
            </div>
          </div>
        </div>
      {/if}
    </section>

    <section class="fetiche-stats-compact mastery-panel fetiche-lcd-screen" aria-label={ui.statsTitle}>
      <div class="fetiche-stat-grid">
        {#each STAT_KEYS as key (key)}
          <div class="fetiche-stat-chip" data-stat={key} title={statChipTitle(key)}>
            <span class="fetiche-stat-label">{statLabels[key]}</span>
            <span class="fetiche-stat-line">
              <span class="fetiche-stat-caption">{ui.statBaseLabel}</span>
              <span class="fetiche-stat-value">{formatNumber(snap.stats[key])}</span>
            </span>
            <span class="fetiche-stat-line">
              <span class="fetiche-stat-caption">{ui.statGainLabel}</span>
              <span class="fetiche-stat-gain">{fmtContrib(snap.gainsPerSec[key])}</span>
            </span>
          </div>
        {/each}
      </div>
    </section>

    <details class="fetiche-hint-details mastery-panel fetiche-lcd-screen">
      <summary>{ui.hintSummary}</summary>
      <p class="fetiche-gains-footnote">{ui.gainsHint}</p>
    </details>
  {/if}
</div>
